import { randomUUID } from 'crypto';

export interface User {
    id: string;
    name: string;
    email: string;
}

export interface CreateUserInput {
    name: string;
    email: string;
}

export interface UpdateUserInput {
    name?: string;
    email?: string;
}

export class UserService {
    private users: Map<string, User>;

    constructor() {
        this.users = new Map();
    }

    listUsers(): User[] {
        return Array.from(this.users.values());
    }

    getUser(id: string): User | undefined {
        return this.users.get(id);
    }

    createUser(input: CreateUserInput): User {
        const newUser: User = {
            id: randomUUID(),
            name: input.name,
            email: input.email,
        };
        this.users.set(newUser.id, newUser);
        return newUser;
    }

    updateUser(id: string, input: UpdateUserInput): User | undefined {
        const user = this.users.get(id);
        if (!user) {
            return undefined;
        }

        if (input.name !== undefined) {
            user.name = input.name;
        }
        if (input.email !== undefined) {
            user.email = input.email;
        }
        this.users.set(id, user); // Update the map with the modified user object
        return user;
    }

    deleteUser(id: string): boolean {
        return this.users.delete(id);
    }
}

import { randomUUID } from 'crypto';

export interface Project {
    id: string;
    name: string;
    description: string;
    memberIds: string[];
}

export interface CreateProjectInput {
    name: string;
    description: string;
}

export interface UpdateProjectInput {
    name?: string;
    description?: string;
}

export class ProjectService {
    private projects: Map<string, Project>;

    constructor() {
        this.projects = new Map();
    }

    listProjects(): Project[] {
        return Array.from(this.projects.values());
    }

    getProject(id: string): Project | undefined {
        return this.projects.get(id);
    }

    createProject(input: CreateProjectInput): Project {
        const newProject: Project = {
            id: randomUUID(),
            name: input.name,
            description: input.description,
            memberIds: [],
        };
        this.projects.set(newProject.id, newProject);
        return newProject;
    }

    updateProject(id: string, input: UpdateProjectInput): Project | undefined {
        const project = this.projects.get(id);
        if (!project) {
            return undefined;
        }

        if (input.name !== undefined) {
            project.name = input.name;
        }
        if (input.description !== undefined) {
            project.description = input.description;
        }
        this.projects.set(id, project);
        return project;
    }

    deleteProject(id: string): boolean {
        return this.projects.delete(id);
    }

    addMember(projectId: string, userId: string): Project | undefined {
        const project = this.projects.get(projectId);
        if (!project) {
            return undefined;
        }
        if (!project.memberIds.includes(userId)) {
            project.memberIds.push(userId);
        }
        this.projects.set(projectId, project);
        return project;
    }

    removeMember(projectId: string, userId: string): Project | undefined {
        const project = this.projects.get(projectId);
        if (!project) {
            return undefined;
        }
        project.memberIds = project.memberIds.filter(id => id !== userId);
        this.projects.set(projectId, project);
        return project;
    }
}

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
    id: string;
    title: string;
    description: string;
    status: TaskStatus;
    assigneeId?: string;
    projectId: string;
}

export interface CreateTaskInput {
    title: string;
    description: string;
    projectId: string;
}

export interface UpdateTaskInput {
    title?: string;
    description?: string;
}

export class TaskService {
    private tasks: Map<string, Task>;

    constructor() {
        this.tasks = new Map();
    }

    listTasks(projectId: string): Task[] {
        return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
    }

    getTask(id: string): Task | undefined {
        return this.tasks.get(id);
    }

    createTask(input: CreateTaskInput): Task {
        const newTask: Task = {
            id: randomUUID(),
            title: input.title,
            description: input.description,
            status: "todo",
            projectId: input.projectId,
        };
        this.tasks.set(newTask.id, newTask);
        return newTask;
    }

    updateTask(id: string, input: UpdateTaskInput): Task | undefined {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }

        if (input.title !== undefined) {
            task.title = input.title;
        }
        if (input.description !== undefined) {
            task.description = input.description;
        }
        this.tasks.set(id, task);
        return task;
    }

    deleteTask(id: string): boolean {
        return this.tasks.delete(id);
    }

    changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }

        const oldStatus = task.status;

        // Enforce forward-only transitions
        if (
            (oldStatus === "todo" && newStatus === "in-progress") ||
            (oldStatus === "todo" && newStatus === "done") || // Allow direct from todo to done for simplicity
            (oldStatus === "in-progress" && newStatus === "done") ||
            (oldStatus === newStatus)
        ) {
            task.status = newStatus;
            this.tasks.set(id, task);

            eventBus.publish('task.statusChanged', {
                taskId: task.id,
                taskTitle: task.title,
                assigneeId: task.assigneeId, // May be undefined
                oldStatus: oldStatus,
                newStatus: newStatus,
            });
            return task;
        }

        return undefined; // Invalid status transition
    }

    assignTask(id: string, assigneeId: string): Task | undefined {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }
        task.assigneeId = assigneeId;
        this.tasks.set(id, task);

        eventBus.publish('task.assigned', {
            taskId: task.id,
            taskTitle: task.title,
            assigneeId: task.assigneeId,
        });

        return task;
    }
}

